// per-call work cost, microseconds (from the lesson)
const WORK_OPT = 1;        // TurboFan-optimized body
const WORK_BYTECODE = 8;   // Ignition/bytecode, never optimized
const DEOPT_BOOKKEEPING = 12;      // ~12us to unwind + re-collect feedback
const RECOMPILE = 100000;          // ~100ms TurboFan recompile, in us
const CALLS = 1000;

// Regime A: stays optimized (guards always hold)
const optimized = WORK_OPT * CALLS;
// Regime B: never optimized, plain bytecode every call
const unoptimized = WORK_BYTECODE * CALLS;
// Regime C: deopt-loop — every call deopts then recompiles then runs bytecode
const deoptLoop = (DEOPT_BOOKKEEPING + RECOMPILE + WORK_BYTECODE) * CALLS;

// how many times slower is the deopt-loop than never optimising?
const ratio = Math.round(deoptLoop / unoptimized);

console.log(`opt=${optimized}us bytecode=${unoptimized}us deoptloop=${deoptLoop}us ratio=${ratio}x`);
